import { test } from "node:test";
import assert from "node:assert/strict";
import { query } from "../src/index.js";

// Shapes as generated by openapi-typescript for the sample model.
type CustomerRow = { id?: string; name?: string; country?: string | null };
type OrderRow = { id?: string; number?: string; status?: "open" | "processing" | "shipped" | "cancelled"; total?: number; createdAt?: string; customer?: CustomerRow | null };
type CustomerWithOrders = CustomerRow & { orders?: OrderRow[] };

test("reference request (spec §31)", () => {
  const doc = query<OrderRow>()
    .select("id", "number", "status", "total", "createdAt")
    .where(f => f.and(f.in("status", ["open", "processing"]), f.gte("createdAt", "2026-01-01T00:00:00Z")))
    .orderBy("createdAt", "desc").orderBy("id")
    .first(100)
    .build();
  assert.deepEqual(doc, {
    version: "1.0",
    select: ["id", "number", "status", "total", "createdAt"],
    where: { type: "logical", operator: "and", children: [
      { type: "comparison", field: "status", operator: "in", value: ["open", "processing"] },
      { type: "comparison", field: "createdAt", operator: "gte", value: "2026-01-01T00:00:00Z" }] },
    orderBy: [{ field: "createdAt", direction: "desc" }, { field: "id", direction: "asc" }],
    page: { first: 100 },
  });
});

test("relationships, null, collections and expansion", () => {
  const doc = query<CustomerWithOrders>()
    .select("name")
    .where(f => f.or(f.eq("country", null), f.not(f.any("orders", o => o.gt("total", 800)))))
    .expand("orders", e => e.select("number", "total").where(o => o.ne("status", "cancelled")).orderBy("total", "desc").first(2))
    .build();
  assert.deepEqual(doc.where, { type: "logical", operator: "or", children: [
    { type: "comparison", field: "country", operator: "eq", value: null },
    { type: "not", operand: { type: "any", relationship: "orders", where: { type: "comparison", field: "total", operator: "gt", value: 800 } } }] });
  assert.deepEqual(doc.expand, [{ relationship: "orders", select: ["number", "total"], where: { type: "comparison", field: "status", operator: "ne", value: "cancelled" }, orderBy: [{ field: "total", direction: "desc" }], first: 2 }]);
  assert.deepEqual(query<OrderRow>().select("customer.name").where(f => f.startsWith("customer.name", "Acme")).build().select, ["customer.name"]);
});

test("aggregation", () => {
  const doc = query<OrderRow>()
    .groupBy("status").aggregate("count", "orders").aggregate("sum", "total", "revenue")
    .having(f => f.gte("orders", 3)).orderBy("revenue", "desc").offset(0).build();
  assert.deepEqual(doc.aggregates, [{ function: "count", alias: "orders" }, { function: "sum", field: "total", alias: "revenue" }]);
  assert.throws(() => query<OrderRow>().select("id").aggregate("count", "n").build());
  assert.throws(() => query<OrderRow>().select("id").after("c").offset(1).build());
});

// Compile-time checks: each line below must be a type error (tsc fails if one is not).
export function typeChecks() {
  // @ts-expect-error unknown field
  query<OrderRow>().select("nope");
  // @ts-expect-error wrong value type for an enum field
  query<OrderRow>().where(f => f.eq("status", "Open"));
  // @ts-expect-error number field compared with a string
  query<OrderRow>().where(f => f.gt("total", "100"));
  // @ts-expect-error collections cannot be traversed with dotted paths
  query<CustomerWithOrders>().select("orders.number");
  // @ts-expect-error 'in' needs at least one value
  query<OrderRow>().where(f => f.in("status", []));
  // @ts-expect-error any() only accepts collection relationships
  query<OrderRow>().where(f => f.any("customer"));
}
